              {mayManage ? (
                <span className="flex justify-end gap-1">
                  {onResend !== undefined ? (
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={() => onResend(invitation.id)}
                    >
                      Resend
                    </Button>
                  ) : null}
                  <Button
                    variant="danger"
                    size="sm"
                    onClick={() => onRevoke(invitation.id)}
                  >
                    Revoke
                  </Button>
                </span>
              ) : null}
            </TableCell>
          </TableRow>
        ))}
      </TableBody>
    </Table>
  );
}
