): Promise<Member> {
  const db = getDb();
  return db.transaction((tx) => {
    const consumed = tx
      .update(invitations)
      .set({ acceptedAt, updatedAt: acceptedAt })
      .where(
        and(
          orgPredicate(invitations.orgId, orgId),
          eq(invitations.id, invitationId),
          isNull(invitations.acceptedAt),
          isNull(invitations.revokedAt),
          gt(invitations.expiresAt, acceptedAt),
        ),
      )
      .returning({ id: invitations.id })
      .get();

    if (!consumed) throw new Error("That invitation is no longer pending");

    const existing = tx
      .select()
      .from(members)
      .where(
        and(
          orgPredicate(members.orgId, orgId),
          eq(members.userId, userId),
        ),
      )
      .get();

    if (existing && existing.archivedAt === null) {
      throw new Error("You are already a member of this organization");
    }

    if (existing) {
      const restored = tx
        .update(members)
        .set({
          role,
          status: "active",
          invitedBy,
          joinedAt: acceptedAt,
          lastSeenAt: null,
          archivedAt: null,
          updatedAt: acceptedAt,
        })
        .where(
          and(
            orgPredicate(members.orgId, orgId),
            eq(members.id, existing.id),
          ),
        )
        .returning()
        .get();

      if (!restored) throw new Error(`Member ${existing.id} could not be restored`);
      return toMember(restored);
    }

    const inserted = tx
      .insert(members)
      .values({
        id: newId(),
        orgId,
        userId,
        role,
        status: "active",
        invitedBy,
        joinedAt: acceptedAt,
        lastSeenAt: null,
        createdAt: acceptedAt,
        updatedAt: acceptedAt,
      })
      .returning()
      .get();

    return toMember(inserted);
  });
}

