/**
 * Re-issuing does not mint a new row: the original is revoked and replaced so
 * the audit trail keeps both, and the old link stops working immediately.
 */
export async function resendInvitation(
  actor: Actor,
  invitationId: InvitationId,
): Promise<Invitation> {
  assertOrgScope(actor, actor.orgId);
  assertCan(actor, "member:invite", orgResource(actor.orgId));

  const previous = requireFound(
    await invitationRepo.findInvitationById(actor.orgId, invitationId),
    "Invitation",
    invitationId,
  );

  if (previous.acceptedAt !== null) {
    throw new Error("That invitation has already been accepted");
  }

  const verdict = await consumeRateLimit(actor.orgId, INVITE_BUCKET);
  if (!verdict.allowed) {
    throw new Error(
      `Invite rate limit reached; try again after ${verdict.resetAt}`,
    );
  }

  const org = requireFound(
    await orgRepo.findOrgById(actor.orgId),
    "Organization",
    actor.orgId,
  );
  if (org.archivedAt !== null) throw new Error("That organization no longer exists");

  await assertInviteAddressAvailable(actor.orgId, previous.email, invitationId);

  const oldLinkWasPending =
    previous.revokedAt === null &&
    previous.expiresAt > toIsoTimestamp(new Date());
  const seatsUsed =
    (await memberRepo.countActiveMembers(actor.orgId)) +
    (await invitationRepo.countPendingInvitations(actor.orgId));
  const seatsToAdd = oldLinkWasPending ? 0 : 1;
  if (wouldExceedLimit(org.plan, "seats", seatsUsed, seatsToAdd)) {
    const limits = getPlanLimits(org.plan);
    throw new Error(
      `Plan ${org.plan} includes ${limits.seats} seats and ${seatsUsed} are taken`,
    );
  }

  await invitationRepo.revokeInvitation(actor.orgId, invitationId);

  const token = randomToken(32);
  const storedInvitation = await invitationRepo.insertInvitation(
    actor.orgId,
    {
      orgId: actor.orgId,
      email: previous.email.toLowerCase(),
      role: previous.role,
      expiresInDays: DEFAULT_EXPIRY_DAYS,
    },
    actor.userId,
    hashToken(token),
  );
  const invitation = { ...storedInvitation, token };

  await usageRepo.recomputeUsage(actor.orgId);
  await emit("member.invited", {
    orgId: actor.orgId,
    actorId: actor.userId,
    occurredAt: invitation.createdAt,
    email: invitation.email,
    role: invitation.role,
  });

  return invitation;
}

async function assertInviteAddressAvailable(
  orgId: Invitation["orgId"],
  email: string,
  exceptInvitationId?: InvitationId,
): Promise<void> {
  if (await memberRepo.findActiveMemberByEmail(orgId, email)) {
    throw new Error(`${email} is already a member of this organization`);
  }
  if (
    await invitationRepo.findPendingInvitationForEmail(
      orgId,
      email,
      exceptInvitationId,
    )
  ) {
    throw new Error(`${email} already has a pending invitation`);
  }
}

